entries[381352] = { ["name"] = "Lauffeuer", ["text"] = "Unbegrenzte Reichweite\nSofort\nDiurna entfesselt Flammen, die Spielercharaktere innerhalb von 50 Metern entzünden und ihnen 21199 Feuerschaden sowie zusätzlich Spielercharakteren innerhalb von 4 Metern um den Einschlagsort 15 Sek. lang alle 1 Sek. 7950 Feuerschaden zuzufügen. Dieser Effekt ist stapelbar.\n\nAugenblicke später entzünden sich die Flammen erneut und belegen Spielercharaktere, die sich nach wie vor innerhalb von 4 um den Einschlagsort aufhalten, mit 'Lauffeuer'.\n\nVon 'Lauffeuer' getroffene Spielercharaktere verbreiten zusätzliche 'Lauffeuer' auf Positionen in der Nähe." }
