entries[381411] = { ["name"] = "Gesalzenes Hackfleisch", ["text"] = "Wirken in 2 sek.\nReagenzien:\nVielleichtfleisch (6), Schuppenbauchmakrele , Grobes Steinsalz\nOptionale Reagenzien:\nFeinschliff (#192) , Geheimzutat (#193)\nRezept für 4 Portionen. Die tatsächliche Anzahl an Portionen hängt von Eurer Kochfertigkeit ab.\nBerufsausbilder:\nKochkunst der Dracheninseln (40)\nKosten:\n1\n50\n\nBenutzen: Stellt im Verlauf von 20 Sek. ( 80357 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 90 Ausdauer.\n65" }
entries[381412] = { ["name"] = "Schicksalhafter Glückskeks", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSchicksalhafte Glückskarte , Thaldraszuskakaopulver (3), Gebäckpakete (5), Seidiger Juwelenstaub (2)\nOptionale Reagenzien:\nFeinschliff (#192) , Geheimzutat (#193)\nBeute von:\nSchicksalhafte Glückskarte\nRezept:\nErhältlich im Auktionshaus\n\nBenutzen: Stellt im Verlauf von 20 Sek. ( 80357 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 76 Hauptwert.\n\nMöge das Glück Euch hold sein!\n70" }
entries[381413] = { ["name"] = "Yusas herzhafter Eintopf", ["text"] = "Wirken in 2 sek.\nReagenzien:\nInselfinnenschwertfisch , Tausendbisspiranha , Mächtige Mammutrippen , Ohn'ahra-Kartoffel , Diverse exotische Gewürze\nOptionale Reagenzien:\nFeinschliff (#192)\nRezept für 2 Festmahle. Die tatsächliche Anzahl an Festmahlen hängt von Eurer Kochfertigkeit ab.\nEntdeckung:\nÄlteste Yusa\nZone:\nEbenen von Ohn'ahra\n\nYusas herzhafter Eintopf\nBenutzen: Stellt einen frischen Topf mit Yusas herzhaftem Eintopf auf, an dem sich alle Spielercharaktere satt essen können.\n\nStellt im Verlauf von 20 Sek. ( 45000 / 5 * 20) Gesundheit und ( 60000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und Euer niedrigster Sekundärwert wird 1 Stunde lang um 70 erhöht.\n70" }
entries[381414] = { ["name"] = "Traumprojektion", ["text"] = "100 Meter Reichweite\nSofort\nHeilt alle Verbündeten in einem Umkreis von 12 Metern sofort um (90% der Zaubermacht) Gesundheit und im Verlauf von 20 Sek. um weitere 381 Gesundheit. Ihr beendet Eure geistige Reise." }
entries[381415] = { ["name"] = "Grals Andacht", ["text"] = "Wirken in 2 sek.\nReagenzien:\nPrismatischer Springer (2), Brüffelchschmorbraten (4), Freche Fischstäbchen (6), Großes himmelblaues Meer (6), Flunkerflatschen (6), Walrossmuffin (3)\nOptionale Reagenzien:\nFeinschliff (#192)\nRezept für 2 Festmahle. Die tatsächliche Anzahl an Festmahlen hängt von Eurer Kochfertigkeit ab.\nWeltquest:\nGemeinschaftliches Festmahl\nZone:\nAzurblaues Gebirge\n\nGroßbankett der Kalu'ak\nBenutzen: Richtet für 3 Min. ein traditionelles Festmahl der Tuskarr aus, an dem sich alle Spielercharaktere satt essen können.\n\nStellt im Verlauf von 20 Sek. ( 45000 / 5 * 20) Gesundheit und ( 60000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und Euer Primärwert wird 1 Stunde lang um 76 erhöht.\n70" }
entries[381416] = { ["name"] = "Wilder Ansturm", ["text"] = "Unbegrenzte Reichweite\nSofort\nRira bereitet einen mächtigen Ansturm auf einen Spielercharakter vor. Nach 14 Sek. stürmt sie auf ihn zu, stößt mit dem ersten Spielercharakter zusammen, der sich im Weg befindet, und fügt ihm 29058238 körperlichen Schaden zu." }
entries[381417] = { ["name"] = "Grals Verehrung", ["text"] = "Wirken in 2 sek.\nReagenzien:\nRaureifflossenthunfisch (2), Flussuferpicknick (4), Aromatische Meeresfrüchteplatte (6), Tausendgrät-Zungenschlitzer (6), Basiliskeneier (6), Schnee im Hörnchen (3)\nOptionale Reagenzien:\nFeinschliff (#192)\nRezept für 2 Festmahle. Die tatsächliche Anzahl an Festmahlen hängt von Eurer Kochfertigkeit ab.\nWeltquest:\nGemeinschaftliches Festmahl\nZone:\nAzurblaues Gebirge\n\nGroßbankett der Kalu'ak\nBenutzen: Richtet für 3 Min. ein traditionelles Festmahl der Tuskarr aus, an dem sich alle Spielercharaktere satt essen können.\n\nStellt im Verlauf von 20 Sek. ( 45000 / 5 * 20) Gesundheit und ( 60000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und Euer Primärwert wird 1 Stunde lang um 76 erhöht.\n70" }
