entries[381846] = { ["name"] = "Aus der Hüfte", ["text"] = "Wenn 'Finsterer Stoß' ein zusätzliches Mal trifft, erhaltet Ihr 1 zusätzlichen Stapel von 'Gelegenheit'. Maximal 6 Stapel.\n\nEinsätze von 'Pistolenschuss' mit halbierten Kosten verbrauchen 1 zusätzlichen Stapel von 'Gelegenheit' und feuern 1 zusätzlichen Schuss ab. Zusätzliche Schüsse erzeugen 1 Combopunkt weniger und verursachen 20% weniger Schaden.\n(500ms Abklingzeit)" }
