entries[381848] = { ["name"] = "Fertiger Prototyp eines majestätischen Geschirrs", ["text"] = "Wirken in 5 sek.\nReagenzien:\nPrototyprahmen für ein majestätisches Geschirr , Büschel Urwolle , Widerstandsfähiges Leder (80), Schimmernder Schuppenbalg (6)\nVerkäufer:\nMurik\nZone:\nAzurblaues Gebirge\nTuskarr von Iskaara - Ruhmstufe 29\nKosten:\n500\n\nVerkäufer:\nRokkutuk\nZone:\nAzurblaues Gebirge\nTuskarr von Iskaara - Ruhmstufe 29\nKosten:\n500\n\nFertiger Prototyp eines majestätischen Geschirrs\nHandwerksmaterial\n\"Wird von Spielercharakteren hergestellt, die den Beruf Lederverarbeitung ausüben. Kann durch Handwerksaufträge erworben werden.\"" }
