entries[381924] = { ["name"] = "Schockdrosselnder Seeleninhalierer", ["text"] = "40 Meter Reichweite\nKanalisiert (Wirken in 4 sek.) 45 sek. Abklingzeit\nBeginnt, einem besonders mächtigen Elementar die Essenz zu entziehen. Stirbt Euer Ziel während dieses Vorgangs oder innerhalb von 30 Sek. nach einer vollständigen Kanalisierung, fangt Ihr seine Seele ein.\n\nNach einem erfolgreichen Fang muss der Antrieb des Geräts 5 Min. lang abkühlen. Zur gleichen Zeit kann immer nur ein Spielercharakter versuchen, einem Elementar die Seele zu entziehen." }
entries[381930] = { ["name"] = "Manaquell", ["text"] = "Elementar\nEure Einsätze von 'Lavaeruption' stellen bei Euch und Euren 4 nächsten Verbündeten innerhalb von 40 Metern 1750 Mana wieder her.\n\nVerbündete können immer nur vom Effekt 'Manaquell' eines Schamanen gleichzeitig profitieren, wobei Heiler priorisiert werden.\n\nWiederherstellung\nEure Einsätze von 'Lavaeruption' und 'Springflut' stellen bei Euch und Euren 4 nächsten Verbündeten innerhalb von 40 Metern 2625 Mana wieder her.\n\nVerbündete können immer nur vom Effekt 'Manaquell' eines Schamanen gleichzeitig profitieren, wobei Heiler priorisiert werden.\n\nVerstärkung\nEure Einsätze von 'Lavaeruption''Sturmschlag' stellen bei Euch und Euren 4 nächsten Verbündeten innerhalb von 40 Metern 2625 Mana wieder her.\n\nVerbündete können immer nur vom Effekt 'Manaquell' eines Schamanen gleichzeitig profitieren, wobei Heiler priorisiert werden." }
