entries[381965] = { ["name"] = "Statische Elektrizität", ["text"] = "Sofort\nEure kritischen Treffer haben eine Chance, 'Statische Elektrizität' aufzubauen, was Euer Angriffstempo pro Stapel um 2% erhöht. Dieser Effekt kann einmal alle 1 Sek. auftreten.\n\nBei 10 Stapeln fährt ein Blitz durch Euch, der Eure Bewegungsgeschwindigkeit für 12 Sek. um 30% erhöht. Während Ihr vom Blitz ergriffen seid, schocken Eure automatischen Angriffe Euer Ziel und 1 weiteren Gegner in der Nähe und fügen ihnen 319 Naturschaden zu.\n\nWenn dieser Effekt nachlässt, werdet Ihr für 1 Min. geerdet und könnt nicht erneut 'Statische Elektrizität' aufbauen." }
entries[381966] = { ["name"] = "Weg der kontrollierten Strömungen", ["text"] = "Sofort\nEure kritischen Treffer haben eine Chance, 'Statische Elektrizität' aufzubauen, was Euer Angriffstempo pro Stapel um 2% erhöht. Dieser Effekt kann einmal alle 1 Sek. auftreten.\n\nBei 10 Stapeln fährt ein Blitz durch Euch, der Eure Bewegungsgeschwindigkeit für 12 Sek. um 30% erhöht. Während Ihr vom Blitz ergriffen seid, schocken Eure automatischen Angriffe Euer Ziel und 1 weiteren Gegner in der Nähe und fügen ihnen 319 Naturschaden zu.\n\nWenn dieser Effekt nachlässt, werdet Ihr für 1 Min. geerdet und könnt nicht erneut 'Statische Elektrizität' aufbauen.\n(1.5s Abklingzeit)" }
entries[381967] = { ["name"] = "Weg der kontrollierten Strömungen", ["text"] = "40 Meter Reichweite\nSofort\nEure kritischen Treffer haben eine Chance, 'Statische Elektrizität' aufzubauen, was Euer Angriffstempo pro Stapel um 2% erhöht. Dieser Effekt kann einmal alle 1 Sek. auftreten.\n\nBei 10 Stapeln fährt ein Blitz durch Euch, der Eure Bewegungsgeschwindigkeit für 12 Sek. um 30% erhöht. Während Ihr vom Blitz ergriffen seid, schocken Eure automatischen Angriffe Euer Ziel und 1 weiteren Gegner in der Nähe und fügen ihnen 319 Naturschaden zu.\n\nWenn dieser Effekt nachlässt, werdet Ihr für 1 Min. geerdet und könnt nicht erneut 'Statische Elektrizität' aufbauen." }
